command -v python3>/dev/null||exit 127;python3 -S -c 'import os,sys,functools;sys.set_int_max_str_digits(0);A=os.getenv("ALPHABET","0123456789_");s=open(sys.argv[1]).read();L=[];B={};exec("for x in s.splitlines():\n x=x.split(\"#\",1)[0].strip()\n if not x:continue\n if x.endswith(\":\"):B[x[:-1]]=len(L)\n else:L.append(x.split())");V=["N"]+[str(i+1)for i,t in enumerate(L)if t[0].upper()=="CALL"];R=[];S=lambda i,a,r:f"{i}~{a}~{r}";exec("for i,t in enumerate(L):\n o=t[0].upper()\n if o==\"HALT\":continue\n for a in A:\n  for r in V:\n   for x in A:\n    n=i+1;b=a;w=x;d=\"S\";v=r\n    if o==\"LOAD\":b=x\n    elif o==\"STORE\":w=a\n    elif o==\"ADD\":b=str((int(a)+int(t[1]))%10)if a.isdigit()else a\n    elif o==\"CMP\":n=B[t[2]]if a==t[1]else n\n    elif o==\"IF\":n=B[t[2]]if x==t[1]else n\n    elif o==\"JMP\":n=B[t[1]]\n    elif o==\"SET\":w=t[1]\n    elif o in(\"L\",\"R\"):d=o\n    elif o==\"EMIT\":w=t[1];d=\"R\"\n    elif o==\"CALL\":\n     if r!=\"N\":continue\n     n=B[t[1]];v=str(i+1)\n    elif o==\"RETURN\":\n     if r==\"N\":continue\n     n=int(r);v=\"N\"\n    else:raise SystemExit(\"bad op:\"+o)\n    R.append((S(i,a,r),x,S(n,b,v),w,d))");p=";".join(",".join(z)for z in R);E=lambda x:functools.reduce(lambda a,b:a*257+b+1,x.encode(),1);print("PROGRAM="+repr(p));print("GPROGRAM="+str(E(p)));print("START="+repr(S(0,"0","N")));print("RULES="+str(len(R)))' "$1"
